/// Read a file's content, mapping IO errors to BivvyError.
fn read_config_file(path: &Path) -> Result<String> {
    fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })
}

/// Load a single config file and parse it into BivvyConfig.
///
/// Supports both YAML and TOML formats, detected by file extension.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the config is invalid.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = read_config_file(path)?;
    parse_config(&content, path)
}

/// Parse config content into BivvyConfig.
///
/// The format is detected from the file extension of `source_path`.
/// Falls back to YAML if the extension is unrecognized.
///
/// # Arguments
///
/// * `content` - The config content to parse
/// * `source_path` - Path used for format detection and error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    let format = ConfigFormat::from_path(source_path).unwrap_or(ConfigFormat::Yaml);
    match format {
        ConfigFormat::Yaml => {
            serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })
        }
        ConfigFormat::Toml => {
            toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })
        }
    }
}

/// Convert a TOML string into a serde_yaml::Value for merging.
///
/// Parses the TOML, then round-trips through JSON to produce a
/// serde_yaml::Value compatible with the merge pipeline.
fn toml_to_yaml_value(content: &str, path: &Path) -> Result<serde_yaml::Value> {
    let toml_value: toml::Value =
        toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: e.to_string(),
        })?;

