307→/// Load config with optional path override.
308→///
309→/// If `config_override` is provided, loads only that file without merging.
310→/// Otherwise, discovers and merges all config files.
311→pub fn load_config(project_root: &Path, config_override: Option<&Path>) -> Result<BivvyConfig> {
312→    if let Some(override_path) = config_override {
313→        // Direct load of specified file, no merging
314→        load_config_file(override_path)
315→    } else {
316→        load_merged_config(project_root)
317→    }
